window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-eb9fc84dcfe15c08"]={"versions": [{"id": "FIG-eb9fc84dcfe15c08", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Adc_SW_queue_prio_mechanism_NONE_queuing_ON</code>) zur Darstellung des dynamischen Verhaltens des AUTOSAR Classic Treibers <code>Adc</code> (MCAL-Schicht, Microcontroller Abstraction Layer) im Zusammenspiel mit dem übergeordneten Nutzer (<code>User</code>) und der unterlagerten Peripherie-Hardware (<code>Hardware::ADC Conversion Unit</code>). Fokus ist die sequentielle Abarbeitung von Software-Konvertierungsanfragen ohne Priorisierungsmechanismus (<code>priority mechanism : NONE</code>) bei aktivierter Software-Warteschlange (<code>queuing : ON</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Instanzen und Schnittstellen:</p>\n<ul class=\"fig-list\">\n<li><code>Generic Elements::Adc User</code>: Aufrufende Software-Entität (z. B. BSW-Modul, CDD oder SWC via IoHwAb).</li>\n<li><code>«module» Adc::Adc</code>: AUTOSAR ADC-Treiberkomponente mit interner Queue-Verwaltung.</li>\n<li><code>«Peripheral» Hardware::ADC Conversion Unit</code>: Hardware-Wandlereinheit des Mikrocontrollers.</li>\n</ul>\n<p class=\"fig-p\">Verwendete synchrone API-Funktionen und asynchrone Rückmeldungen/Notifications:</p>\n<ul class=\"fig-list\">\n<li><code>Adc_EnableGroupNotification(Group_x)</code>: Aktivierung der Gruppen-Benachrichtigung für Kanalgruppen.</li>\n<li><code>Adc_StartGroupConversion(Group_x)</code>: Starten bzw. Einreihen einer Gruppenkonvertierung.</li>\n<li><code>Adc_Notification_Group_x</code>: Benachrichtigungs-Callback an den User bei abgeschlossener Wandlung.</li>\n<li>Hardware-Trigger und Statusinteraktionen: <code>start conversion (Group_x)</code> sowie Interrupt/Statusrückmeldung <code>conversion completed (Group_x)</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf zeigt das FIFO-Verhalten einer Software-Queue ohne Prioritätsmechanismus:</p>\n<ol class=\"fig-list\">\n<li><code>User</code> aktiviert Benachrichtigungen für Gruppe 1 und 2 über <code>Adc_EnableGroupNotification(Group_x)</code>.</li>\n<li><code>User</code> startet Konvertierung von Gruppe 1 (<code>Adc_StartGroupConversion(Group1)</code>). Da die Hardware frei ist, leitet das ADC-Modul die Wandlung direkt an die <code>Hardware::ADC Conversion Unit</code> weiter (<code>start conversion (Group1)</code>).</li>\n<li>Während Gruppe 1 konvertiert wird (<code>conversion Group1 ongoing</code>), fordert der <code>User</code> die Konvertierung von Gruppe 2 an (<code>Adc_StartGroupConversion(Group2)</code>). Das ADC-Modul puffert die Anforderung intern (<code>store conversion request(Group2)</code>) und kehrt synchron zum Aufrufer zurück.</li>\n<li>Nach Abschluss der Wandlung von Gruppe 1 meldet die Hardware <code>conversion completed (Group1)</code>. Der ADC-Treiber startet unmittelbar die in der Queue wartende Konvertierung von Gruppe 2 auf der Hardware (<code>start conversion(Group2)</code>) und ruft den Callback <code>Adc_Notification_Group_1</code> auf.</li>\n<li>Während Gruppe 2 gewandelt wird (<code>conversion Group2 ongoing</code>), fordert der <code>User</code> erneut die Konvertierung von Gruppe 1 an (<code>Adc_StartGroupConversion(Group1)</code>). Die Anforderung wird in der Software-Queue abgelegt (<code>store conversion request(Group1)</code>).</li>\n<li>Nach Abschluss von Gruppe 2 (<code>conversion completed (Group2)</code>) triggert der Treiber sofort die anstehende Konvertierung von Gruppe 1 (<code>start conversion(Group1)</code>) und setzt den Callback <code>Adc_Notification_Group_2</code> ab.</li>\n<li>Nach Wandlungsende von Gruppe 1 (<code>conversion completed (Group1)</code>) folgt abschließend <code>Adc_Notification_Group_1</code>. Da keine weiteren Aufträge in der Queue vorliegen, geht der Treiber in den Ruhezustand.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Konfigurationsparameter: <code>AdcPriorityMechanism</code> = <code>ADC_PRIORITY_NONE</code>, <code>AdcEnableQueuing</code> = <code>STD_ON</code>.</li>\n<li>Verhalten bei Konvertierungsanfragen: Trifft eine Wandlungsanforderung ein, während die ADC-Hardware belegt ist, wird der Auftrag in einer Software-Warteschlange (FIFO) zwischengespeichert und nach Fertigstellung der laufenden Wandlung automatisch gestartet.</li>\n<li>Timing/Verschränkung: Das Einreihen in die Queue blockiert den Aufrufer nicht (nicht-blockierende API). Callbacks (<code>Adc_Notification_&lt;Group&gt;</code>) werden nach Wandlungsende aufgerufen, während bereits die nächste geordnete Konvertierung gestartet wurde.</li>\n<li>Die Queue-Tiefe muss in der Treiberkonfiguration ausreichend bemessen sein, um Überläufe bei dicht aufeinanderfolgenden Anfragen zu vermeiden.</li>\n</ul>"}, {"id": "FIG-f8a3e429c8f84b72", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Adc_SW_queue_prio_mechanism_NONE_queuing_ON</code>) zur Darstellung des dynamischen Verhaltens des AUTOSAR Classic Treibers <code>Adc</code> (MCAL-Schicht, Microcontroller Abstraction Layer) im Zusammenspiel mit dem übergeordneten Nutzer (<code>User</code>) und der unterlagerten Peripherie-Hardware (<code>Hardware::ADC Conversion Unit</code>). Fokus ist die sequentielle Abarbeitung von Software-Konvertierungsanfragen ohne Priorisierungsmechanismus (<code>priority mechanism : NONE</code>) bei aktivierter Software-Warteschlange (<code>queuing : ON</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Instanzen und Schnittstellen:</p>\n<ul class=\"fig-list\">\n<li><code>Generic Elements::Adc User</code>: Aufrufende Software-Entität (z. B. BSW-Modul, CDD oder SWC via IoHwAb).</li>\n<li><code>«module» Adc::Adc</code>: AUTOSAR ADC-Treiberkomponente mit interner Queue-Verwaltung.</li>\n<li><code>«Peripheral» Hardware::ADC Conversion Unit</code>: Hardware-Wandlereinheit des Mikrocontrollers.</li>\n</ul>\n<p class=\"fig-p\">Verwendete synchrone API-Funktionen und asynchrone Rückmeldungen/Notifications:</p>\n<ul class=\"fig-list\">\n<li><code>Adc_EnableGroupNotification(Group_x)</code>: Aktivierung der Gruppen-Benachrichtigung für Kanalgruppen.</li>\n<li><code>Adc_StartGroupConversion(Group_x)</code>: Starten bzw. Einreihen einer Gruppenkonvertierung.</li>\n<li><code>Adc_Notification_Group_x</code>: Benachrichtigungs-Callback an den User bei abgeschlossener Wandlung.</li>\n<li>Hardware-Trigger und Statusinteraktionen: <code>start conversion (Group_x)</code> sowie Interrupt/Statusrückmeldung <code>conversion completed (Group_x)</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf zeigt das FIFO-Verhalten einer Software-Queue ohne Prioritätsmechanismus:</p>\n<ol class=\"fig-list\">\n<li><code>User</code> aktiviert Benachrichtigungen für Gruppe 1 und 2 über <code>Adc_EnableGroupNotification(Group_x)</code>.</li>\n<li><code>User</code> startet Konvertierung von Gruppe 1 (<code>Adc_StartGroupConversion(Group1)</code>). Da die Hardware frei ist, leitet das ADC-Modul die Wandlung direkt an die <code>Hardware::ADC Conversion Unit</code> weiter (<code>start conversion (Group1)</code>).</li>\n<li>Während Gruppe 1 konvertiert wird (<code>conversion Group1 ongoing</code>), fordert der <code>User</code> die Konvertierung von Gruppe 2 an (<code>Adc_StartGroupConversion(Group2)</code>). Das ADC-Modul puffert die Anforderung intern (<code>store conversion request(Group2)</code>) und kehrt synchron zum Aufrufer zurück.</li>\n<li>Nach Abschluss der Wandlung von Gruppe 1 meldet die Hardware <code>conversion completed (Group1)</code>. Der ADC-Treiber startet unmittelbar die in der Queue wartende Konvertierung von Gruppe 2 auf der Hardware (<code>start conversion(Group2)</code>) und ruft den Callback <code>Adc_Notification_Group_1</code> auf.</li>\n<li>Während Gruppe 2 gewandelt wird (<code>conversion Group2 ongoing</code>), fordert der <code>User</code> erneut die Konvertierung von Gruppe 1 an (<code>Adc_StartGroupConversion(Group1)</code>). Die Anforderung wird in der Software-Queue abgelegt (<code>store conversion request(Group1)</code>).</li>\n<li>Nach Abschluss von Gruppe 2 (<code>conversion completed (Group2)</code>) triggert der Treiber sofort die anstehende Konvertierung von Gruppe 1 (<code>start conversion(Group1)</code>) und setzt den Callback <code>Adc_Notification_Group_2</code> ab.</li>\n<li>Nach Wandlungsende von Gruppe 1 (<code>conversion completed (Group1)</code>) folgt abschließend <code>Adc_Notification_Group_1</code>. Da keine weiteren Aufträge in der Queue vorliegen, geht der Treiber in den Ruhezustand.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Konfigurationsparameter: <code>AdcPriorityMechanism</code> = <code>ADC_PRIORITY_NONE</code>, <code>AdcEnableQueuing</code> = <code>STD_ON</code>.</li>\n<li>Verhalten bei Konvertierungsanfragen: Trifft eine Wandlungsanforderung ein, während die ADC-Hardware belegt ist, wird der Auftrag in einer Software-Warteschlange (FIFO) zwischengespeichert und nach Fertigstellung der laufenden Wandlung automatisch gestartet.</li>\n<li>Timing/Verschränkung: Das Einreihen in die Queue blockiert den Aufrufer nicht (nicht-blockierende API). Callbacks (<code>Adc_Notification_&lt;Group&gt;</code>) werden nach Wandlungsende aufgerufen, während bereits die nächste geordnete Konvertierung gestartet wurde.</li>\n<li>Die Queue-Tiefe muss in der Treiberkonfiguration ausreichend bemessen sein, um Überläufe bei dicht aufeinanderfolgenden Anfragen zu vermeiden.</li>\n</ul>"}, {"id": "FIG-b4fbef65b98acbf7", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Adc_SW_queue_prio_mechanism_NONE_queuing_ON</code>) zur Darstellung des dynamischen Verhaltens des AUTOSAR Classic Treibers <code>Adc</code> (MCAL-Schicht, Microcontroller Abstraction Layer) im Zusammenspiel mit dem übergeordneten Nutzer (<code>User</code>) und der unterlagerten Peripherie-Hardware (<code>Hardware::ADC Conversion Unit</code>). Fokus ist die sequentielle Abarbeitung von Software-Konvertierungsanfragen ohne Priorisierungsmechanismus (<code>priority mechanism : NONE</code>) bei aktivierter Software-Warteschlange (<code>queuing : ON</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Instanzen und Schnittstellen:</p>\n<ul class=\"fig-list\">\n<li><code>Adc User</code>: Aufrufende Software-Entität (z. B. BSW-Modul, CDD oder SWC via IoHwAb).</li>\n<li><code>«module» Adc</code>: AUTOSAR ADC-Treiberkomponente mit interner Queue-Verwaltung.</li>\n<li><code>«Peripheral» ADC Conversion Unit</code>: Hardware-Wandlereinheit des Mikrocontrollers.</li>\n</ul>\n<p class=\"fig-p\">Verwendete synchrone API-Funktionen und asynchrone Rückmeldungen/Notifications:</p>\n<ul class=\"fig-list\">\n<li><code>Adc_EnableGroupNotification(Group_x)</code> mit Rückkehr <code>Adc_EnableGroupNotification()</code>: Aktivierung der Gruppen-Benachrichtigung für Kanalgruppen.</li>\n<li><code>Adc_StartGroupConversion(Group_x)</code> mit Rückkehr <code>Adc_StartGroupConversion()</code>: Starten bzw. Einreihen einer Gruppenkonvertierung.</li>\n<li><code>Adc_Notification_Group_x()</code>: Benachrichtigungs-Callback an den User bei abgeschlossener Wandlung mit Rückkehr <code>Adc_Notification_Group_x()</code>.</li>\n<li>Hardware-Trigger und Statusinteraktionen: <code>start conversion (Group_x)</code> bzw. <code>start conversion(Group_x)</code> sowie Interrupt/Statusrückmeldung <code>conversion completed (Group_x)</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf zeigt das FIFO-Verhalten einer Software-Queue ohne Prioritätsmechanismus:</p>\n<ol class=\"fig-list\">\n<li><code>Adc User</code> aktiviert Benachrichtigungen für Gruppe 1 und 2 über <code>Adc_EnableGroupNotification(Group_x)</code>.</li>\n<li><code>Adc User</code> startet Konvertierung von Gruppe 1 (<code>Adc_StartGroupConversion(Group1)</code>). Da die Hardware frei ist, leitet das ADC-Modul die Wandlung direkt an die <code>ADC Conversion Unit</code> weiter (<code>start conversion (Group1)</code>).</li>\n<li>Während Gruppe 1 konvertiert wird (<code>conversion Group1 ongoing</code>), fordert der <code>Adc User</code> die Konvertierung von Gruppe 2 an (<code>Adc_StartGroupConversion(Group2)</code>). Das ADC-Modul puffert die Anforderung intern (<code>store conversion request(Group2)</code>) und kehrt synchron zum Aufrufer zurück (<code>Adc_StartGroupConversion()</code>).</li>\n<li>Nach Abschluss der Wandlung von Gruppe 1 meldet die Hardware <code>conversion completed (Group1)</code>. Der ADC-Treiber startet unmittelbar die in der Queue wartende Konvertierung von Gruppe 2 auf der Hardware (<code>start conversion(Group2)</code>) und ruft den Callback <code>Adc_Notification_Group_1()</code> auf.</li>\n<li>Während Gruppe 2 gewandelt wird (<code>conversion Group2 ongoing</code>), fordert der <code>Adc User</code> erneut die Konvertierung von Gruppe 1 an (<code>Adc_StartGroupConversion(Group1)</code>). Die Anforderung wird in der Software-Queue abgelegt (<code>store conversion request(Group1)</code>).</li>\n<li>Nach Abschluss von Gruppe 2 (<code>conversion completed (Group2)</code>) triggert der Treiber sofort die anstehende Konvertierung von Gruppe 1 (<code>start conversion(Group1)</code>) und setzt den Callback <code>Adc_Notification_Group_2()</code> ab.</li>\n<li>Nach Wandlungsende von Gruppe 1 (<code>conversion completed (Group1)</code>) folgt abschließend <code>Adc_Notification_Group_1()</code>. Da keine weiteren Aufträge in der Queue vorliegen, geht der Treiber in den Ruhezustand.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Konfigurationsparameter: <code>AdcPriorityMechanism</code> = <code>ADC_PRIORITY_NONE</code>, <code>AdcEnableQueuing</code> = <code>STD_ON</code>.</li>\n<li>Verhalten bei Konvertierungsanfragen: Trifft eine Wandlungsanforderung ein, während die ADC-Hardware belegt ist, wird der Auftrag in einer Software-Warteschlange (FIFO) zwischengespeichert und nach Fertigstellung der laufenden Wandlung automatisch gestartet.</li>\n<li>Timing/Verschränkung: Das Einreihen in die Queue blockiert den Aufrufer nicht (nicht-blockierende API). Callbacks (<code>Adc_Notification_&lt;Group&gt;</code>) werden nach Wandlungsende aufgerufen, während bereits die nächste geordnete Konvertierung gestartet wurde.</li>\n<li>Die Queue-Tiefe muss in der Treiberkonfiguration ausreichend bemessen sein, um Überläufe bei dicht aufeinanderfolgenden Anfragen zu vermeiden.</li>\n</ul>"}], "trans": [{"from": "FIG-eb9fc84dcfe15c08", "to": "FIG-f8a3e429c8f84b72", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-f8a3e429c8f84b72", "to": "FIG-b4fbef65b98acbf7", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>Lifelines / Header</strong>:</li>\n<li><code>Generic Elements::Adc User</code> wurde zu <code>Adc User</code> vereinfacht (Wegfall des Paketpräfixes).</li>\n<li><code>«module» Adc::Adc</code> wurde zu <code>«module» Adc</code> vereinfacht (Wegfall des Paketpräfixes).</li>\n<li><code>«Peripheral» Hardware::ADC Conversion Unit</code> wurde zu <code>«Peripheral» ADC Conversion Unit</code> umbenannt (Wegfall des Paketpräfixes).</li>\n<li><strong>Nachrichtenbeschriftungen</strong>:</li>\n<li>Rückgabenachrichten und Callbacks wurden formal mit leeren Klammern <code>()</code> versehen:</li>\n<li><code>Adc_EnableGroupNotification</code> -> <code>Adc_EnableGroupNotification()</code></li>\n<li><code>Adc_StartGroupConversion</code> -> <code>Adc_StartGroupConversion()</code></li>\n<li><code>Adc_Notification_Group_1</code> -> <code>Adc_Notification_Group_1()</code></li>\n<li><code>Adc_Notification_Group_2</code> -> <code>Adc_Notification_Group_2()</code></li>\n</ul>"}]};
